-- SIDEWORLD Group Runtime V1, additive service-only schema and six RPCs.
-- Filename generated by Supabase CLI v2.119.0 in GitHub Actions on 2026-10-24.
-- PRODUCTION NOT APPLIED: SQL promotion is subject to verified backup/restore
-- readiness, migration parity and explicit approval, independent of PR merge.
-- Existing Solo Player runtime and canonical universes are unchanged.

create table player.group_sessions (
  id uuid primary key default gen_random_uuid(),
  release_id uuid not null references canon.quest_releases(id) on delete restrict,
  host_actor_id uuid not null references auth.users(id) on delete restrict,
  start_request_id uuid not null,
  mode text not null check (mode in ('couple','team')),
  status text not null default 'forming'
    check (status in ('forming','in_progress','completed','abandoned')),
  expected_players smallint not null check (expected_players between 2 and 4),
  engine_content_hash text not null check (engine_content_hash ~ '^[0-9a-f]{64}$'),
  sequence integer not null default 0 check (sequence between 0 and 10000),
  progress jsonb not null check (
    jsonb_typeof(progress) = 'object' and pg_column_size(progress) <= 262144
  ),
  invite_hash text not null check (invite_hash ~ '^[0-9a-f]{64}$'),
  invite_expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sw_group_mode_size check (
    (mode='couple' and expected_players=2) or
    (mode='team' and expected_players between 3 and 4)
  ),
  constraint sw_group_create_idempotence unique(host_actor_id,release_id,start_request_id)
);
create index sw_group_host_recent on player.group_sessions(host_actor_id,updated_at desc);
create index sw_group_release_idx on player.group_sessions(release_id);

create table player.group_members (
  session_id uuid not null references player.group_sessions(id) on delete restrict,
  actor_id uuid not null references auth.users(id) on delete restrict,
  role_id text not null check (role_id ~ '^[a-z][a-z0-9_-]{0,39}$'),
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  primary key (session_id,actor_id),
  unique (session_id,role_id)
);
create index sw_group_members_actor_idx on player.group_members(actor_id,session_id)
  where left_at is null;

create table player.group_receipts (
  session_id uuid not null references player.group_sessions(id) on delete restrict,
  request_id uuid not null,
  actor_id uuid not null references auth.users(id) on delete restrict,
  fingerprint text not null check (fingerprint ~ '^[0-9a-f]{64}$'),
  result_sequence integer not null check (result_sequence between 1 and 10000),
  result_status text not null check (result_status in ('in_progress','completed')),
  created_at timestamptz not null default now(),
  primary key (session_id,request_id)
);
create index sw_group_receipt_latest on player.group_receipts(session_id,result_sequence desc);

-- These tables hold invite hashes, membership, private answers and all events.
-- No direct Data API grants, no role policies, including service_role direct table access.
alter table player.group_sessions enable row level security;
alter table player.group_members enable row level security;
alter table player.group_receipts enable row level security;
revoke all on player.group_sessions,player.group_members,player.group_receipts
  from public,anon,authenticated,service_role;

-- SERVER-ONLY. A trusted Player route derives p_actor from a freshly verified
-- identity and calls using a server-held service_role key, never a browser key.
create function public.sideworld_group_create_v1(
  p_actor uuid,p_release_id uuid,p_mode text,p_request_id uuid,
  p_initial_progress jsonb,p_invite_hash text,p_invite_expires_at timestamptz
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  r canon.quest_releases;
  v player.group_sessions;
  defined jsonb;
  required_size integer;
  first_role text;
begin
  if p_actor is null or p_release_id is null or p_request_id is null
      or p_mode not in ('couple','team') or p_mode is null
      or p_invite_hash is null or p_invite_hash !~ '^[0-9a-f]{64}$'
      or p_invite_expires_at is null or p_invite_expires_at <= now()
      or p_invite_expires_at > now() + interval '24 hours'
      or not player.can_use_release_v1(p_actor,p_release_id) then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into r from canon.quest_releases where id=p_release_id;
  if r.id is null then return jsonb_build_object('kind','unavailable'); end if;
  defined := r.document->'experienceModes'->p_mode;
  if jsonb_typeof(defined) is distinct from 'object'
      or defined->'minPlayers' is null
      or defined->'maxPlayers' is null
      or jsonb_typeof(defined->'roles') is distinct from 'array' then
    return jsonb_build_object('kind','unavailable');
  end if;
  if jsonb_typeof(defined->'minPlayers') <> 'number'
      or jsonb_typeof(defined->'maxPlayers') <> 'number' then
    return jsonb_build_object('kind','invalid');
  end if;
  required_size := (defined->>'maxPlayers')::integer;
  if (defined->>'minPlayers')::integer <> required_size
      or not ((p_mode='couple' and required_size=2)
        or (p_mode='team' and required_size between 3 and 4))
      or jsonb_array_length(defined->'roles') <> required_size then
    return jsonb_build_object('kind','invalid');
  end if;
  first_role := defined->'roles'->0->>'id';
  if first_role is null or first_role !~ '^[a-z][a-z0-9_-]{0,39}$' then
    return jsonb_build_object('kind','invalid');
  end if;
  if p_initial_progress is null or jsonb_typeof(p_initial_progress) <> 'object'
      or pg_column_size(p_initial_progress) > 262144
      or p_initial_progress->'engineVersion' is distinct from '1'::jsonb
      or p_initial_progress->>'questId' is distinct from r.source_draft_id::text
      or p_initial_progress->'revision' is distinct from to_jsonb(r.source_revision)
      or p_initial_progress->>'contentHash' is distinct from r.engine_content_hash
      or p_initial_progress->'sequence' is distinct from '0'::jsonb
      or p_initial_progress->'events' is distinct from '[]'::jsonb then
    return jsonb_build_object('kind','invalid');
  end if;
  insert into player.group_sessions (
    release_id,host_actor_id,start_request_id,mode,expected_players,
    engine_content_hash,progress,invite_hash,invite_expires_at
  ) values (
    p_release_id,p_actor,p_request_id,p_mode,required_size,
    r.engine_content_hash,p_initial_progress,p_invite_hash,p_invite_expires_at
  )
  on conflict(host_actor_id,release_id,start_request_id) do nothing
  returning * into v;
  if v.id is not null then
    insert into player.group_members(session_id,actor_id,role_id)
      values(v.id,p_actor,first_role);
    return jsonb_build_object('kind','started','new',true,'sessionId',v.id,
      'versionId',v.release_id,'mode',v.mode,'status',v.status,
      'expectedPlayers',v.expected_players);
  end if;
  select * into v from player.group_sessions
    where host_actor_id=p_actor and release_id=p_release_id
      and start_request_id=p_request_id;
  if v.id is null or v.mode <> p_mode
      or v.engine_content_hash <> r.engine_content_hash then
    return jsonb_build_object('kind','conflict');
  end if;
  return jsonb_build_object('kind','started','new',false,'sessionId',v.id,
    'versionId',v.release_id,'mode',v.mode,'status',v.status,
    'expectedPlayers',v.expected_players);
end $$;

-- Only valid, unexpired invite proof plus independently entitled Auth identity.
-- Row lock serializes competing joins and ensures single-use role assignments.
create function public.sideworld_group_join_v1(
  p_actor uuid,p_session_id uuid,p_invite_hash text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v player.group_sessions;
  r canon.quest_releases;
  existing player.group_members;
  role text;
  occupied integer;
begin
  if p_actor is null or p_session_id is null or p_invite_hash is null
      or p_invite_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into v from player.group_sessions where id=p_session_id for update;
  if v.id is null or v.invite_hash <> p_invite_hash or v.invite_expires_at<=now()
      or not player.can_use_release_v1(p_actor,v.release_id) then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into existing from player.group_members
    where session_id=v.id and actor_id=p_actor;
  if existing.session_id is not null then
    if existing.left_at is not null or v.status='abandoned' then
      return jsonb_build_object('kind','unavailable');
    end if;
    return jsonb_build_object('kind','joined','sessionId',v.id,
      'roleId',existing.role_id,'status',v.status);
  end if;
  if v.status <> 'forming' then return jsonb_build_object('kind','unavailable'); end if;
  select * into r from canon.quest_releases where id=v.release_id;
  select count(*) into occupied from player.group_members
    where session_id=v.id and left_at is null;
  if occupied >= v.expected_players then return jsonb_build_object('kind','unavailable'); end if;
  select e.value->>'id' into role
  from jsonb_array_elements(r.document->'experienceModes'->v.mode->'roles')
    with ordinality as e(value,ordinal)
  where not exists (
    select 1 from player.group_members m
      where m.session_id=v.id and m.role_id=e.value->>'id'
  )
  order by e.ordinal limit 1;
  if role is null or role !~ '^[a-z][a-z0-9_-]{0,39}$' then
    return jsonb_build_object('kind','unavailable');
  end if;
  insert into player.group_members(session_id,actor_id,role_id)
    values(v.id,p_actor,role);
  if occupied + 1 = v.expected_players then
    update player.group_sessions set status='in_progress',updated_at=now()
      where id=v.id;
    v.status := 'in_progress';
  end if;
  return jsonb_build_object('kind','joined','sessionId',v.id,
    'roleId',role,'status',v.status);
end $$;

-- Exact projection expected by the checked-in Player group-read adapter.
create function public.sideworld_group_get_v1(
  p_actor uuid,p_session_id uuid
) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare
  v player.group_sessions;
  member player.group_members;
  mode_visibility text;
  occupied integer;
begin
  if p_actor is null or p_session_id is null then return null; end if;
  select * into v from player.group_sessions where id=p_session_id;
  if v.id is null or not player.can_use_release_v1(p_actor,v.release_id) then return null; end if;
  select * into member from player.group_members
    where session_id=v.id and actor_id=p_actor and left_at is null;
  if member.session_id is null then return null; end if;
  select visibility into mode_visibility from canon.quest_releases where id=v.release_id;
  select count(*) into occupied from player.group_members
    where session_id=v.id and left_at is null;
  return jsonb_build_object('sessionId',v.id,'actorId',p_actor,
    'versionId',v.release_id,'accessMode',mode_visibility,
    'mode',v.mode,'status',v.status,'roleId',member.role_id,
    'joinedPlayers',occupied,'expectedPlayers',v.expected_players,
    'engineContentHash',v.engine_content_hash,'progress',v.progress);
end $$;

-- Lightweight actor-specific idempotency check. No raw progress ever leaves
-- this RPC, and only the service-held actor identity may request receipts.
create function public.sideworld_group_receipt_get_v1(
  p_actor uuid,p_session_id uuid,p_request_id uuid
) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v player.group_sessions; rec player.group_receipts;
begin
  if p_actor is null or p_session_id is null or p_request_id is null then return null; end if;
  select * into v from player.group_sessions where id=p_session_id;
  if v.id is null or not player.can_use_release_v1(p_actor,v.release_id)
      or not exists(select 1 from player.group_members m
        where m.session_id=v.id and m.actor_id=p_actor and m.left_at is null) then
    return null;
  end if;
  select * into rec from player.group_receipts
    where session_id=v.id and request_id=p_request_id and actor_id=p_actor;
  if rec.session_id is null then return null; end if;
  return jsonb_build_object('fingerprint',rec.fingerprint,
    'resultSequence',rec.result_sequence,'status',rec.result_status);
end $$;

-- One transaction/row lock for actor-member CAS, immutable release binding,
-- idempotent duplicate resolution and terminal completion.
create function public.sideworld_group_apply_v1(
  p_actor uuid,p_session_id uuid,p_request_id uuid,p_fingerprint text,
  p_expected_sequence integer,p_next_progress jsonb,p_is_terminal boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v player.group_sessions; prior player.group_receipts; next_status text;
begin
  if p_actor is null or p_session_id is null or p_request_id is null
      or p_fingerprint is null or p_fingerprint !~ '^[0-9a-f]{64}$'
      or p_expected_sequence is null or p_expected_sequence not between 0 and 9999
      or p_is_terminal is null then
    return jsonb_build_object('kind','invalid');
  end if;
  select * into v from player.group_sessions where id=p_session_id for update;
  if v.id is null or not player.can_use_release_v1(p_actor,v.release_id)
      or not exists(select 1 from player.group_members m
        where m.session_id=v.id and m.actor_id=p_actor and m.left_at is null) then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into prior from player.group_receipts
    where session_id=v.id and request_id=p_request_id;
  if prior.session_id is not null then
    if prior.actor_id <> p_actor or prior.fingerprint <> p_fingerprint then
      return jsonb_build_object('kind','conflict');
    end if;
    return jsonb_build_object('kind','duplicate',
      'resultSequence',prior.result_sequence,'status',prior.result_status);
  end if;
  if v.status<>'in_progress' or v.sequence<>p_expected_sequence then
    return jsonb_build_object('kind','conflict');
  end if;
  if p_next_progress is null or jsonb_typeof(p_next_progress)<>'object'
      or pg_column_size(p_next_progress)>262144
      or p_next_progress->'engineVersion' is distinct from '1'::jsonb
      or p_next_progress->>'questId' is distinct from v.progress->>'questId'
      or p_next_progress->'revision' is distinct from v.progress->'revision'
      or p_next_progress->>'contentHash' is distinct from v.engine_content_hash
      or p_next_progress->'sequence' is distinct from to_jsonb(p_expected_sequence+1)
      or jsonb_typeof(p_next_progress->'events') is distinct from 'array'
      or jsonb_typeof(v.progress->'events') is distinct from 'array' then
    return jsonb_build_object('kind','invalid');
  end if;
  if jsonb_array_length(p_next_progress->'events') <> p_expected_sequence+1
      or ((p_next_progress->'events') - p_expected_sequence)
         is distinct from (v.progress->'events') then
    return jsonb_build_object('kind','invalid');
  end if;
  next_status := case when p_is_terminal then 'completed' else 'in_progress' end;
  update player.group_sessions set progress=p_next_progress,
      sequence=p_expected_sequence+1,status=next_status,updated_at=now()
      where id=v.id;
  insert into player.group_receipts
    (session_id,request_id,actor_id,fingerprint,result_sequence,result_status)
    values(v.id,p_request_id,p_actor,p_fingerprint,p_expected_sequence+1,next_status);
  delete from player.group_receipts where session_id=v.id and request_id in (
    select request_id from player.group_receipts
     where session_id=v.id order by result_sequence desc offset 32
  );
  return jsonb_build_object('kind','saved',
    'resultSequence',p_expected_sequence+1,'status',next_status);
end $$;

-- V1 disallows host transfer/replacement mid-adventure. Any participant leaving
-- marks the whole group abandoned; durable records remain for audit/recovery.
create function public.sideworld_group_leave_v1(
  p_actor uuid,p_session_id uuid
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v player.group_sessions; member player.group_members;
begin
  if p_actor is null or p_session_id is null then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into v from player.group_sessions where id=p_session_id for update;
  if v.id is null or not player.can_use_release_v1(p_actor,v.release_id) then
    return jsonb_build_object('kind','unavailable');
  end if;
  select * into member from player.group_members
    where session_id=v.id and actor_id=p_actor;
  if member.session_id is null then return jsonb_build_object('kind','unavailable'); end if;
  if member.left_at is null then
    update player.group_members set left_at=now()
      where session_id=v.id and actor_id=p_actor;
    if v.status in ('forming','in_progress') then
      update player.group_sessions set status='abandoned',updated_at=now() where id=v.id;
    end if;
  end if;
  return jsonb_build_object('kind','left');
end $$;

-- PostgreSQL defaults new functions to PUBLIC EXECUTE: revoke explicitly.
revoke all on function public.sideworld_group_create_v1(
    uuid,uuid,text,uuid,jsonb,text,timestamptz),
  public.sideworld_group_join_v1(uuid,uuid,text),
  public.sideworld_group_get_v1(uuid,uuid),
  public.sideworld_group_receipt_get_v1(uuid,uuid,uuid),
  public.sideworld_group_apply_v1(uuid,uuid,uuid,text,integer,jsonb,boolean),
  public.sideworld_group_leave_v1(uuid,uuid)
  from public,anon,authenticated,service_role;

grant execute on function public.sideworld_group_create_v1(
    uuid,uuid,text,uuid,jsonb,text,timestamptz),
  public.sideworld_group_join_v1(uuid,uuid,text),
  public.sideworld_group_get_v1(uuid,uuid),
  public.sideworld_group_receipt_get_v1(uuid,uuid,uuid),
  public.sideworld_group_apply_v1(uuid,uuid,uuid,text,integer,jsonb,boolean),
  public.sideworld_group_leave_v1(uuid,uuid)
  to service_role;

comment on table player.group_sessions is
  'Private, immutable-release-pinned shared quest progress; no client table access.';
comment on table player.group_members is
  'Private member and author-assigned role binding; no client table access.';
comment on table player.group_receipts is
  'Per-actor bounded idempotency receipts for atomic group actions.';
